     ========================================================== */

  .quota-builder .modal {
    padding-left: 6px;
    padding-right: 6px;
    overflow-y: auto;
  }

  .quota-builder .modal-dialog {
    width: auto;
    max-width: calc(100% - 12px);
    margin: 8px auto;
  }

  .quota-builder .modal-content {
