  }

  .quota-builder {
    overflow-x: hidden;
  }
}


/* ============================================================
   SMALL PHONES
   ============================================================ */
@media (max-width: 480px) {

  .quota-builder {
    padding: 0 7px;
  }

  .quota-builder .qb-page-title {
    font-size: 1.8rem;
  }

  .quota-builder .qb-back-btn {
    width: 32px;
    height: 32px;
  }


  /* Progress */
  .quota-builder .quota-progress .progress-steps {
    min-width: 520px;
  }

  .quota-builder .quota-progress .step-number {
