  }


  /* Quarter */
  .quota-builder .quarter-title {
    font-size: 16px;
  }

  .quota-builder .right-total {
    font-size: 16px;
  }


  /* Month table */
  .quota-builder .month-table {
    min-width: 450px;
  }

  .quota-builder .month-table th,
  .quota-builder .month-table td {
    font-size: 9px;
    padding: 7px 5px;
  }

  .quota-builder .quota-input {
    width: 82px;
    max-width: 82px;
  }


  /* Distribution */
  .quota-builder .distribution-box {
    padding: 12px;
  }

  .quota-builder .quarter-grid {
    gap: 7px;
  }

  .quota-builder .quarter-cards {
    padding: 11px 7px;
  }

  .quota-builder .quarter-name {
    font-size: 12px;
  }

  .quota-builder .quarter-value {
    font-size: 11px;
  }
}


/* ============================================================
   EXTRA SMALL PHONES
   ============================================================ */
@media (max-width: 360px) {

  .quota-builder {
    padding: 0 5px;
  }

  .quota-builder .qb-page-title {
    font-size: 1.65rem;
  }

  .quota-builder .m-b-xs {
    font-size: 1.8rem;
  }

  .quota-builder .fixed-yearly-card {
    padding: 12px;
  }

  .quota-builder .fixed-value {
    font-size: 19px;
  }


  /* Progress */
  .quota-builder .quota-progress .progress-steps {
    min-width: 490px;
  }

  .quota-builder .quota-progress .step-number {
    width: 135px !important;
    font-size: 9px;
  }


  /* Quarter summary -> one column */
  .quota-builder .quarter-grid {
    grid-template-columns: 1fr;
  }

  .quota-builder .quarter-cards {
    text-align: left;
  }


  /* Month table remains horizontally scrollable */
  .quota-builder .month-table {
    min-width: 420px;
  }


  /* Modal */
  .quota-builder .modal-dialog {
    max-width: calc(100% - 8px);
    margin: 5px auto;
  }
}

/* ============================================================
   FINAL MOBILE BUTTON ALIGNMENT
   ============================================================ */

@media (max-width: 767px) {

  .quota-builder .text-right {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex-wrap: wrap;
    width: 100%;
  }

  .quota-builder .text-right .btn {
    flex: 0 1 auto;
    white-space: nowrap;
    margin: 0;
  }

}


/* ============================================================
   SMALL PHONE BUTTON ALIGNMENT
   ============================================================ */

@media (max-width: 480px) {

  .quota-builder .text-right {
    justify-content: stretch;
  }

  .quota-builder .text-right .btn {
    flex: 1 1 0;
    min-width: 0;
    text-align: center;
  }

}


/* ============================================================
   VERY SMALL PHONE
   ============================================================ */

@media (max-width: 360px) {

  .quota-builder .text-right {
    flex-direction: column;
    align-items: stretch;
  }

  .quota-builder .text-right .btn {
    width: 100%;
    flex: none;
  }

}

sp_widget.script:
(function() {

    /* populate the 'data' object */
    data.isEdit = !!options.quota_batch_id;
    data.quotaModel = {};
    data.distribution = [];
    data.sys_id = $sp.getParameter('sys_id');

    data.isTerritoryEnabled =
        new x_ctans_incentnow.IncentNowUtils().isTerritoryExtensionActive() === true;
		var TERRITORY_FIELD = 'x_ctans_territory_territory';

		data.currencySymbol = gs.getProperty('x_ctans_incentnow.currency_symbol', '$');
		data.currencyPosition = gs.getProperty('x_ctans_incentnow.currency_position','before');

    //data.incentnowAdForm= $sp.getWidget('incentnow-form-advanced',{table:"x_ctans_incentnow_quota",view:""});
    /* ================= FISCAL CALENDAR ================= */

    data.fiscalPeriods = [];

    var periodGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_calendar');
    periodGR.addQuery('active', true);
    periodGR.orderByDesc('fiscal_year_name');
    //periodGR.setLimit(12);
    periodGR.query();

    while (periodGR.next()) {
        data.fiscalPeriods.push({
            id: periodGR.getUniqueValue(),
            name: periodGR.getValue('fiscal_year_name'),
            startDate: '',
            endDate: ''
        });
    }

		/* ================= TERRITORIES ================= */

		data.territories = [];

		if (data.isTerritoryEnabled) {

				var terrGR = new GlideRecordSecure('sn_tp_territory');

				// Admins - Show all territories
				if (
						gs.getUser().hasRole('admin') ||
						gs.hasRole('x_ctans_incentnow.admin')
				) {

						var qualifier = new sn_sales_territory.TerritoryUtil()
								.getTerritoryReferenceQualifier();

						if (qualifier)
								terrGR.addEncodedQuery(qualifier);

						terrGR.orderBy('name');
						terrGR.query();
				}

				// Territory Admin - Show assigned territory + all child territories
				else {

						var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
						profileGR.addQuery('user', gs.getUserID());
						profileGR.query();

						if (profileGR.next() && profileGR.getValue('x_ctans_territory_territory')) {

								var territoryIds = [];

								function getChildren(parentId) {

										if (territoryIds.indexOf(parentId) > -1)
												return;

										territoryIds.push(parentId);

										var childGR = new GlideRecordSecure('sn_tp_territory');
										childGR.addQuery('parent', parentId);
										childGR.query();

										while (childGR.next()) {
												getChildren(childGR.getUniqueValue());
										}
								}

								getChildren(profileGR.getValue('x_ctans_territory_territory'));

								terrGR.addQuery('sys_id', 'IN', territoryIds.join(','));
								terrGR.orderBy('name');
								terrGR.query();
						}
				}

				var allTerritories = {};

				while (terrGR.next()) {
						allTerritories[terrGR.getUniqueValue()] = {
								id: terrGR.getUniqueValue(),
								name: terrGR.getDisplayValue('name'),
								parent: terrGR.getValue('parent'),
								children: []
						};
				}

				// Build hierarchy
				for (var id in allTerritories) {
						var territory = allTerritories[id];
						if (territory.parent && allTerritories[territory.parent]) {
								allTerritories[territory.parent].children.push(territory);
						}
				}

				function addChildren(parent, level) {

						parent.children.sort(function(a, b) {
								return a.name.localeCompare(b.name);
						});

						parent.children.forEach(function(child) {

								data.territories.push({
										id: child.id,
										name: child.name,
										label: '\u2003\u2003\u2003'.repeat(level) + child.name
								});

								addChildren(child, level + 1);
						});
				}

				// Add root territories
				for (var key in allTerritories) {

						if (!allTerritories[key].parent) {

								data.territories.push({
										id: allTerritories[key].id,
										name: allTerritories[key].name,
										label: allTerritories[key].name
								});

								addChildren(allTerritories[key], 1);
						}
				}
		}

    /* ================= BUSINESS UNITS ================= */

    data.businessUnits = [];

    var buGR = new GlideRecordSecure('business_unit');

    if (
        (gs.getUser().hasRole('admin')) ||
        gs.hasRole('x_ctans_incentnow.admin') ||
        gs.hasRole('x_ctans_incentnow.business_group_executive')
    ) {

        buGR.orderBy('name');
        buGR.query();

    } else if (gs.hasRole('x_ctans_incentnow.business_group_admin')) {

        var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        profileGR.addQuery('user', gs.getUserID());
        profileGR.query();

        if (profileGR.next() && profileGR.getValue('business_unit')) {

            var rootBU = profileGR.getValue('business_unit');

            var buIds = [];

            function getChildren(parentId) {

                buIds.push(parentId);

                var childGR = new GlideRecordSecure('business_unit');
                childGR.addQuery('parent', parentId);
                childGR.query();

                while (childGR.next()) {
                    getChildren(childGR.getUniqueValue());
                }
            }

            getChildren(rootBU);

            buGR.addQuery('sys_id', 'IN', buIds.join(','));
            buGR.orderBy('name');
            buGR.query();
        }
    }

    var allBU = {};

    while (buGR.next()) {

        allBU[buGR.getUniqueValue()] = {
            id: buGR.getUniqueValue(),
            name: buGR.getValue('name'),
            parent: buGR.getValue('parent'),
            children: []
        };
    }

    // Build hierarchy
    for (var id in allBU) {

        var bu = allBU[id];

        if (bu.parent && allBU[bu.parent]) {
            allBU[bu.parent].children.push(bu);
        }
    }

    data.businessUnits = [];

    function addChildren(parent, level) {

        parent.children.sort(function(a, b) {
            return a.name.localeCompare(b.name);
        });

        parent.children.forEach(function(child) {

            data.businessUnits.push({
                id: child.id,
                name: child.name,
                label: '\u2003\u2003\u2003'.repeat(level) + child.name
            });

            addChildren(child, level + 1);
        });
    }

    // Add root BUs first
    for (var key in allBU) {

        if (!allBU[key].parent) {

            data.businessUnits.push({
                id: allBU[key].id,
                name: allBU[key].name,
                label: allBU[key].name
            });

            addChildren(allBU[key], 1);
        }
    }

    /* ================= USERS ================= */

    data.availableUsers = [];

    var userGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
    userGR.orderBy('name');
    userGR.query();

    while (userGR.next()) {
        data.availableUsers.push({
            id: userGR.getUniqueValue(),
            name: userGR.getValue('name'),
            email: userGR.getValue('email')
        });
    }

    /* ================= CHECK EXISTING ================= */

    if (input && input.action === 'check_existing') {

        data.count = 0;

        var countGR = new GlideAggregate('x_ctans_incentnow_user_quota_assignment');
        countGR.addQuery('quota.financial_year', input.period_id);
        countGR.addAggregate('COUNT');
        countGR.query();

        if (countGR.next()) {
            data.count = parseInt(countGR.getAggregate('COUNT'), 10);
        }
    }

    /* ================= GET USER INFO ================= */

    if (input && input.action === 'get_user_info') {
        var uGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        if (uGR.get(input.user_id)) {
            var businessUnit = '';
            var businessUnitId = '';
            if (uGR.getValue('business_unit')) {
                var bu = new GlideRecordSecure('business_unit');
                if (bu.get(uGR.getValue('business_unit'))) {
                    businessUnit = bu.getValue('name');
                    businessUnitId = bu.getUniqueValue();
                }
            }
            data.userInfo = {
                name: uGR.getValue('name'),
                email: uGR.getValue('email'),
                businessUnit: businessUnit,
                businessUnitId: businessUnitId
            };
        }
    }

    /* ================= GET Record ================= */

    if (input && input.action === 'getRecord') {

        data.record = {};

        var grQuota = new GlideRecordSecure('x_ctans_incentnow_quota'); // ✅ fixed table
        gs.info("Frequency: " + grQuota.getValue('quota_frequency'));

        if (grQuota.get(input.sys_id)) {

            data.sys_id = grQuota.getUniqueValue();

            var territoryValue = '';

            if (data.isTerritoryEnabled && grQuota.isValidField(TERRITORY_FIELD)) {
                territoryValue = grQuota.getValue(TERRITORY_FIELD) || '';
            }

            data.record = {
                status: grQuota.getValue('status'),
                name: grQuota.getValue('name'),
                notes: grQuota.getValue('description'),
                fiscalPeriodId: grQuota.getValue('fiscal_year'),
                valueType: grQuota.getValue('quota_metric'),
                frequency: grQuota.getValue('quota_frequency'),
                businessDimension: grQuota.getValue('business_dimension'),
                businessUnit: grQuota.getValue('business_unit'),
                territory: territoryValue,


                yearlyValue: grQuota.getValue('quota_frequency') === 'annually' ? grQuota.getValue('target_value') : '',
                quarterlyValue: grQuota.getValue('quota_frequency') === 'quarterly' ? grQuota.getValue('target_value') : '',
                monthlyValue: grQuota.getValue('quota_frequency') === 'monthly' ? grQuota.getValue('target_value') : ''
            };
        }

        var qpGR = new GlideRecordSecure('x_ctans_incentnow_quota_period');
        qpGR.addQuery('quota', input.sys_id);
        qpGR.orderBy('period_type');
        qpGR.orderBy('period_number');
        qpGR.query();

        var quarters = {};
        var months = {};

        while (qpGR.next()) {

            var type = qpGR.getValue('period_type');
            var num = parseInt(qpGR.getValue('period_number'));
            var val = Number(qpGR.getValue('target_value') || 0);

            // QUARTERS
            if (type === 'quarter') {
                quarters[num] = {
                    total: val,
                    months: []
                };
            }

            // MONTHS
            if (type === 'month') {
                var qIndex = Math.ceil(num / 3);
                if (!months[qIndex]) months[qIndex] = [];

                months[qIndex].push({
                    value: val
                });
            }
        }

        // Merge months into quarters
        var monthNames = [
            ["January", "February", "March"],
            ["April", "May", "June"],
            ["July", "August", "September"],
            ["October", "November", "December"]
        ];

        for (var q = 1; q <= 4; q++) {

            var quarterMonths = [];

            for (var m = 0; m < 3; m++) {

                var monthData = (months[q] && months[q][m]) ? months[q][m] : {
                    value: 0
                };

                quarterMonths.push({
                    name: monthNames[q - 1][m],
                    value: Number(monthData.value || 0)
                });
            }

            data.distribution.push({
                total: quarters[q] ? Number(quarters[q].total || 0) : 0,
                months: quarterMonths
            });
        }
    }

    /* ================= GET BU USERS ================= */

    if (input && input.action === 'get_bu_users') {
        data.users = [];
        var buUserGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        buUserGR.addQuery('business_unit', input.bu_id);
        buUserGR.query();
        while (buUserGR.next()) {
            var buName = '';
            if (buUserGR.getValue('business_unit')) {
                var b = new GlideRecordSecure('business_unit');
                if (b.get(buUserGR.getValue('business_unit'))) {
                    buName = b.getValue('name');
                }
            }
            data.users.push({
                id: buUserGR.getUniqueValue(),
                name: buUserGR.getValue('name'),
                email: buUserGR.getValue('email'),
                businessUnit: buName
            });
        }
    }

    /* ================= SAVE QUOTAS ================= */

    if (input && input.action === 'saveQuota') {

        data.status = "error";
        data.message = "";

        var q = input.quotaData;
        var sysId = input.sys_id; // ✅ FIXED (single source)

        // ✅ UNIQUE NAME CHECK
        var check = new GlideRecordSecure('x_ctans_incentnow_quota');
        check.addQuery('name', q.name);

        if (sysId) {
            check.addQuery('sys_id', '!=', sysId);
        }

        check.query();

        if (check.next()) {
            data.status = "error";
            data.message = "Quota name already exists";
            return;
        }

        // ✅ SINGLE GlideRecord (removed duplicate)
        var quotaGR = new GlideRecordSecure('x_ctans_incentnow_quota');

        if (quotaGR.get(sysId)) {

        } else {
            quotaGR.initialize();
        }

        // ✅ VALIDATION
        if (!q.name || !q.fiscalPeriodId || !q.frequency || !q.valueType) {
            data.message = "Missing required fields";
            return;
        }

        if (q.businessDimension === 'business_unit' && !q.businessUnit) {
            data.message = "Business Unit is required";
            return;
        }

        if (q.businessDimension === 'territory') {

            if (!data.isTerritoryEnabled) {
                data.message =
                    'Territory configuration is unavailable because the ' +
                    'Territory extension is not active.';
                return;
            }

            if (!q.territory) {
                data.message = 'Territory is required';
                return;
            }
        }

        var targetValue = Number(q.quotaValue || 0);

        quotaGR.name = q.name;
        quotaGR.description = q.notes;
        quotaGR.fiscal_year = q.fiscalPeriodId;
        quotaGR.quota_frequency = q.frequency;
        quotaGR.quota_metric = q.valueType;
        quotaGR.target_value = targetValue;
        quotaGR.business_dimension = q.businessDimension;
        quotaGR.business_unit = q.businessUnit || '';

        if (data.isTerritoryEnabled && quotaGR.isValidField(TERRITORY_FIELD)) {
            quotaGR.setValue(TERRITORY_FIELD, q.territory || '');
        }

        var newSysId;

        if (sysId) {
            quotaGR.update(); //  update
            newSysId = sysId;
        } else {
            newSysId = quotaGR.insert(); //  insert
        }

        //  IMPORTANT FIX: refresh distribution
        updateQuotaPeriods(newSysId, q.fiscalPeriodId, input.distribution || []);

        data.status = "success";
        data.sys_id = newSysId;
    }


    function updateQuotaPeriods(quotaSysId, fiscalYear, distribution) {

        // DELETE OLD (this is what your code was missing)
        var del = new GlideRecordSecure('x_ctans_incentnow_quota_period');
        del.addQuery('quota', quotaSysId);
        del.query();
        while (del.next()) {
            del.deleteRecord();
        }

        var fiscalToQuotaMap = {};

        function create(periodType) {

            var fp = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');
            fp.addQuery('fiscal_year', fiscalYear);
            fp.addQuery('period_type', periodType);
            fp.orderBy('period_number');
            fp.query();

            while (fp.next()) {

                var qp = new GlideRecordSecure('x_ctans_incentnow_quota_period');
                qp.initialize();

                qp.quota = quotaSysId;
                qp.fiscal_period = fp.sys_id;
                qp.period_type = fp.period_type;
                qp.period_number = fp.period_number;
                qp.calculation_mode = 'driven_by_annual_quota';

                if (periodType === 'year') {
                    qp.target_value = Number(input.quotaData.quotaValue || 0);
                }

                if (periodType === 'quarter') {
                    var qIndex = parseInt(fp.period_number) - 1;
                    qp.target_value = Number(
                        (distribution[qIndex] && distribution[qIndex].total) || 0
                    );
                }

                if (periodType === 'month') {
                    var mIndex = parseInt(fp.period_number) - 1;
                    var qIndex = Math.floor(mIndex / 3);
                    var mInQ = mIndex % 3;

                    qp.target_value = Number(
                        (distribution[qIndex] &&
                            distribution[qIndex].months &&
                            distribution[qIndex].months[mInQ] &&
                            distribution[qIndex].months[mInQ].value) || 0
                    );
                }

                var qpSysId = qp.insert();
                fiscalToQuotaMap[fp.sys_id.toString()] = qpSysId;
            }
        }

        create('year');
        create('quarter');
        create('month');
    }

})();
